use ark_ff::PrimeField;
use rayon::prelude::*;

/// A tensor-bucketed vector (TBV) over a field `F`.
/// Each bucket is of power-of-two length `k`, scaled by `eta`,
/// and generated by the tensor span of `z` (length = log2(k)).
#[derive(Clone, Debug)]
pub struct Bucket<F: PrimeField> {
    pub k: usize,
    pub eta: F,
    pub z: Vec<F>,
}

#[derive(Clone, Debug)]
pub struct TBV<F: PrimeField> {
    /// Total length K (power of two).
    pub k_total: usize,
    /// Buckets in order.
    pub buckets: Vec<Bucket<F>>,
}

impl<F: PrimeField> TBV<F> {
    /// Create a TBV whose real buckets occupy a prefix of the logical domain.
    /// Any remaining suffix up to `k_total` is implicitly zero.
    pub fn new(k_total: usize, buckets: Vec<Bucket<F>>) -> Self {
        let sum: usize = buckets.iter().map(|b| b.k).sum();
        assert!(
            sum <= k_total,
            "bucket lengths sum {} exceeds k_total {}",
            sum,
            k_total
        );
        assert!(k_total.is_power_of_two(), "k_total must be power of two");
        assert!(
            buckets.iter().all(|bucket| {
                bucket.k.is_power_of_two() && bucket.z.len() == bucket.k.ilog2() as usize
            }),
            "invalid TBV bucket"
        );
        assert!(
            buckets.windows(2).all(|window| window[0].k >= window[1].k),
            "TBV buckets must be in non-increasing order"
        );
        TBV { k_total, buckets }
    }

    /// Even-odd split: returns (even part, odd part), each of length K/2.
    pub fn eo_split(self) -> (TBV<F>, TBV<F>) {
        assert!(self.k_total > 1, "cannot split a length-one TBV");
        let k_half = self.k_total / 2;

        let singleton_start = self
            .buckets
            .iter()
            .position(|bucket| bucket.k == 1)
            .unwrap_or(self.buckets.len());
        let (wide, singletons) = self.buckets.split_at(singleton_start);

        let split_wide: Vec<(Bucket<F>, Bucket<F>)> = wide
            .par_iter()
            .map(|bucket| {
                let z0 = bucket.z[0];
                let tail = bucket.z[1..].to_vec();
                (
                    Bucket {
                        k: bucket.k / 2,
                        eta: bucket.eta,
                        z: tail.clone(),
                    },
                    Bucket {
                        k: bucket.k / 2,
                        eta: bucket.eta * z0,
                        z: tail,
                    },
                )
            })
            .collect();

        let mut even = Vec::with_capacity(wide.len() + singletons.len().div_ceil(2));
        let mut odd = Vec::with_capacity(wide.len() + singletons.len() / 2);
        for (even_bucket, odd_bucket) in split_wide {
            even.push(even_bucket);
            odd.push(odd_bucket);
        }
        for pair in singletons.chunks(2) {
            even.push(pair[0].clone());
            if let Some(odd_bucket) = pair.get(1) {
                odd.push(odd_bucket.clone());
            }
        }

        (TBV::new(k_half, even), TBV::new(k_half, odd))
    }

    /// Even-odd fold: returns ζ' = ζ_O + y * ζ_E, still a TBV of length K/2.
    pub fn eo_fold(self, y: F) -> TBV<F> {
        assert!(self.k_total > 1, "cannot fold a length-one TBV");
        let k_half = self.k_total / 2;
        let singleton_start = self
            .buckets
            .iter()
            .position(|bucket| bucket.k == 1)
            .unwrap_or(self.buckets.len());
        let mut old_buckets = self.buckets;
        let singletons = old_buckets.split_off(singleton_start);

        let mut new_buckets: Vec<Bucket<F>> = old_buckets
            .into_par_iter()
            .map(|mut bucket| {
                bucket.eta *= F::one() + y * bucket.z[0];
                bucket.z.remove(0);
                bucket.k /= 2;
                bucket
            })
            .collect();

        for pair in singletons.chunks(2) {
            let eta = pair[0].eta + pair.get(1).map_or_else(F::zero, |right| y * right.eta);
            new_buckets.push(Bucket {
                k: 1,
                eta,
                z: Vec::new(),
            });
        }

        TBV::new(k_half, new_buckets)
    }

    pub fn eo_fold_in_place(&mut self, y: F) {
        let old = std::mem::replace(
            self,
            TBV {
                k_total: 1,
                buckets: Vec::new(),
            },
        );
        *self = old.eo_fold(y);
    }

    /// Inner product <a, ζ> without materializing ζ; a must have length K.
    pub fn inner_product(&self, a: &[F]) -> F {
        assert!(
            a.len() == self.k_total,
            "input vector length {} != TBV length {}",
            a.len(),
            self.k_total
        );

        let mut offsets = Vec::with_capacity(self.buckets.len());
        let mut current_offset = 0;
        for b in &self.buckets {
            offsets.push(current_offset);
            current_offset += b.k;
        }

        self.buckets
            .par_iter()
            .zip(offsets.par_iter())
            .map(|(b, &offset)| {
                let segment = &a[offset..offset + b.k];
                // Parallel between buckets, serial within buckets
                let folded =
                    crate::xi_rev::xi_rev_ip_from_challenges_and_vector_serial(segment, &b.z);
                b.eta * folded
            })
            .reduce(|| F::zero(), |acc, val| acc + val)
    }

    /// Materialize the TBV into a dense vector of length k_total.
    pub fn expand(&self) -> Vec<F> {
        let mut expanded: Vec<F> = self
            .buckets
            .par_iter()
            .flat_map(|b| expand_bucket(b))
            .collect();
        expanded.resize(self.k_total, F::zero());
        expanded
    }

    pub fn ip_with_tbv(&self, other: &TBV<F>) -> F {
        if self.buckets.len() != other.buckets.len() {
            panic!("TBV bucket counts do not match");
        }

        self.buckets
            .par_iter()
            .zip(other.buckets.par_iter())
            .map(|(b1, b2)| {
                if (b1.k as usize) != (b2.k as usize) {
                    panic!("TBV bucket sizes do not match");
                }
                if b1.eta.is_zero() || b2.eta.is_zero() {
                    F::zero()
                } else {
                    let folded = crate::xi_rev::xi_ip_from_challenges(&b1.z, &b2.z);
                    b1.eta * b2.eta * folded
                }
            })
            .reduce(|| F::zero(), |acc, val| acc + val)
    }

    pub fn new_from_challenges(bucket_sizes: &[usize], challenges: &[F]) -> Self {
        let mut total_k = 0;
        let mut offsets = Vec::with_capacity(bucket_sizes.len());
        for &k in bucket_sizes {
            offsets.push(total_k);
            total_k += k;
        }

        assert!(
            challenges.len() < usize::BITS as usize,
            "challenge count exceeds the platform length"
        );
        let logical_k = 1usize << challenges.len();
        assert!(
            total_k <= logical_k,
            "real bucket prefix exceeds the logical tensor length"
        );

        let buckets: Vec<Bucket<F>> = bucket_sizes
            .par_iter()
            .zip(offsets.par_iter())
            .map(|(&cur_k, &offset)| {
                if offset % cur_k != 0 || !cur_k.is_power_of_two() {
                    panic!("invalid bucket sizes");
                }

                let mut eta_index = offset / cur_k;
                let cur_log_k = cur_k.ilog2() as usize;
                let cur_z = challenges[0..cur_log_k].to_vec();

                let mut eta_acc = F::one();
                let mut j = 0;
                while eta_index > 0 {
                    if eta_index % 2 == 1 {
                        eta_acc *= challenges[cur_log_k + j];
                    }
                    eta_index /= 2;
                    j += 1;
                }

                Bucket {
                    k: cur_k,
                    eta: eta_acc,
                    z: cur_z,
                }
            })
            .collect();

        TBV::new(logical_k, buckets)
    }

    pub fn ip_with_xi_rev_from_challenges(&self, challenges: &[F]) -> F {
        let bucket_sizes: Vec<usize> = self.buckets.iter().map(|b| b.k).collect();
        let tbv_other = TBV::new_from_challenges(&bucket_sizes, challenges);
        self.ip_with_tbv(&tbv_other)
    }
}

/// Expand a single bucket into its dense tensor span, scaled by eta.
fn expand_bucket<F: PrimeField>(b: &Bucket<F>) -> Vec<F> {
    let mut v = Vec::with_capacity(b.k);
    v.push(F::one());
    for &c in &b.z {
        let current_len = v.len();
        for i in 0..current_len {
            v.push(v[i] * c);
        }
    }
    assert_eq!(v.len(), b.k, "bucket expansion length mismatch");
    for x in &mut v {
        *x *= b.eta;
    }
    v
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::utils::eo_fold_in_place;
    use ark_bls12_381::Fr;
    use ark_ff::Zero;

    fn sample_tbv() -> TBV<Fr> {
        // K = 8, with real buckets ordered by decreasing size.
        TBV::new(
            8,
            vec![
                Bucket {
                    k: 4,
                    eta: Fr::from(7u64),
                    z: vec![Fr::from(11u64), Fr::from(13u64)],
                },
                Bucket {
                    k: 2,
                    eta: Fr::from(3u64),
                    z: vec![Fr::from(5u64)],
                },
                Bucket {
                    k: 1,
                    eta: Fr::from(1u64),
                    z: vec![],
                },
                Bucket {
                    k: 1,
                    eta: Fr::from(2u64),
                    z: vec![],
                },
            ],
        )
    }

    #[test]
    fn decreasing_tbv_keeps_the_logical_tail_implicit() {
        let tbv = TBV::new(
            16,
            vec![
                Bucket {
                    k: 8,
                    eta: Fr::from(1u64),
                    z: vec![Fr::from(2u64); 3],
                },
                Bucket {
                    k: 4,
                    eta: Fr::from(3u64),
                    z: vec![Fr::from(5u64); 2],
                },
                Bucket {
                    k: 2,
                    eta: Fr::from(7u64),
                    z: vec![Fr::from(11u64)],
                },
            ],
        );

        assert_eq!(tbv.buckets.len(), 3);
        assert_eq!(tbv.buckets.iter().map(|bucket| bucket.k).sum::<usize>(), 14);
        let expanded = tbv.expand();
        assert_eq!(expanded.len(), 16);
        assert_eq!(&expanded[14..], &[Fr::zero(), Fr::zero()]);
    }

    #[test]
    fn eo_fold_pairs_the_singleton_suffix_without_padding_buckets() {
        let tbv = TBV::new(
            8,
            vec![
                Bucket {
                    k: 4,
                    eta: Fr::from(2u64),
                    z: vec![Fr::from(3u64), Fr::from(5u64)],
                },
                Bucket {
                    k: 1,
                    eta: Fr::from(7u64),
                    z: Vec::new(),
                },
                Bucket {
                    k: 1,
                    eta: Fr::from(11u64),
                    z: Vec::new(),
                },
            ],
        );
        let challenge = Fr::from(13u64);
        let dense = tbv.expand();
        let expected = dense
            .chunks_exact(2)
            .map(|pair| pair[0] + challenge * pair[1])
            .collect::<Vec<_>>();

        let folded = tbv.eo_fold(challenge);

        assert_eq!(folded.k_total, 4);
        assert_eq!(
            folded
                .buckets
                .iter()
                .map(|bucket| bucket.k)
                .collect::<Vec<_>>(),
            vec![2, 1]
        );
        assert_eq!(folded.expand(), expected);
    }

    #[test]
    fn test_eo_split_and_fold_shapes() {
        let tbv = sample_tbv();
        let (o, e) = tbv.eo_split();
        assert_eq!(o.k_total, 4);
        assert_eq!(e.k_total, 4);
        assert_eq!(o.buckets.len(), e.buckets.len());

        let y = Fr::from(3u64);
        let folded = sample_tbv().eo_fold(y);
        assert_eq!(folded.k_total, 4);
    }

    #[test]
    fn test_inner_product_matches_expansion() {
        let tbv = sample_tbv();
        let expanded = tbv.expand();
        let a: Vec<Fr> = (1u64..=8u64).map(Fr::from).collect();
        let ip_expand: Fr = expanded.iter().zip(a.iter()).map(|(x, y)| *x * *y).sum();

        let ip_tbv = tbv.inner_product(&a);
        assert_eq!(ip_expand, ip_tbv);
    }

    #[test]
    fn test_expand_split_fold() {
        let tbv = sample_tbv();
        let expanded = tbv.expand();

        // Split expected using dense expansion
        let mut exp_o = Vec::new();
        let mut exp_e = Vec::new();
        for (idx, val) in expanded.iter().enumerate() {
            if idx % 2 == 0 {
                exp_o.push(*val);
            } else {
                exp_e.push(*val);
            }
        }
        let (tbv_o, tbv_e) = sample_tbv().eo_split();
        assert_eq!(tbv_o.expand(), exp_o);
        assert_eq!(tbv_e.expand(), exp_e);

        // Fold expected using dense expansion
        let y = Fr::from(9u64);
        let mut exp_fold = Vec::new();
        for i in 0..exp_o.len() {
            exp_fold.push(exp_o[i] + y * exp_e[i]);
        }
        let folded = sample_tbv().eo_fold(y);
        assert_eq!(folded.expand(), exp_fold);
    }

    #[test]
    fn test_eo_fold_matches_dense_fold() {
        let tbv = sample_tbv();
        let y = Fr::from(5u64);
        let mut expanded = tbv.expand();

        // dense fold using utils::eo_fold_in_place
        let folded_dense = {
            let slice = eo_fold_in_place(&mut expanded, y);
            slice.to_vec()
        };

        let folded_tbv = sample_tbv().eo_fold(y).expand();
        assert_eq!(folded_tbv, folded_dense);
    }

    #[test]
    fn test_ip_with_xi_rev_from_challenges_consistency() {
        use crate::xi_rev::xi_rev_from_challenges;
        let tbv = sample_tbv(); // total_k = 8, log_k = 3
        let challenges = vec![Fr::from(2u64), Fr::from(3u64), Fr::from(5u64)];

        // Method 1: Use the optimized TBV method
        let ip_optimized = tbv.ip_with_xi_rev_from_challenges(&challenges);

        // Method 2: Expand TBV and challenges, then compute dot product
        let tbv_dense = sample_tbv().expand();
        let xi_dense = xi_rev_from_challenges(&challenges);

        assert_eq!(tbv_dense.len(), xi_dense.len(), "Dense lengths must match");

        let ip_dense: Fr = tbv_dense
            .iter()
            .zip(xi_dense.iter())
            .map(|(a, b)| *a * *b)
            .sum();

        assert_eq!(
            ip_optimized, ip_dense,
            "Optimized IP should match dense expansion IP"
        );
    }
}
